using System.Linq;using UnityEngine;
public static class InspectOrganicGround{public static object Main(){var w=Object.FindAnyObjectByType<ExplorationWorld>();return w.GetComponentsInChildren<MeshRenderer>().Where(r=>r.name=="Forest ground"||r.name.StartsWith("Road adventure")).OrderBy(r=>(r.bounds.center-w.vehicle.position).sqrMagnitude).Take(3).Select(r=>new{name=r.name,shader=r.sharedMaterial.shader.name,weights=r.GetComponent<MeshFilter>().sharedMesh.colors.Take(3).Select(c=>c.ToString()).ToArray(),maps=r.sharedMaterial.GetTexture("_MossMap")==null?"missing":r.sharedMaterial.GetTexture("_MossMap").name}).ToArray();}}
